import{_ as l,a0 as p,w as u,s as r,I as s,x as e,ao as a,a1 as o,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"詳解在 Ubuntu 中引導到救援模式或緊急模式 | LCTT x X-CMD","titleTemplate":false,"description":"詳解在 Ubuntu 中引導到救援模式或緊急模式 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"詳解在 Ubuntu 中引導到救援模式或緊急模式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"詳解在 Ubuntu 中引導到救援模式或緊急模式 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220518 How To Boot Into Rescue Mode Or Emergency Mode In Ubuntu 22.04 - 20.04 - 18.04","title":"詳解在 Ubuntu 中引導到救援模式或緊急模式","tag":"202206","desc":""},"relativePath":"202206/20220518 How To Boot Into Rescue Mode Or Emergency Mode In Ubuntu 22.04 - 20.04 - 18.04.md","filePath":"[post].md"}'),d={name:"202206/20220518 How To Boot Into Rescue Mode Or Emergency Mode In Ubuntu 22.04 - 20.04 - 18.04.md"};function c(h,t,b,g,k,m){const n=p("Link");return u(),r("div",null,[t[21]||(t[21]=s("h1",{id:"詳解在-ubuntu-中引導到救援模式或緊急模式",tabindex:"-1"},[e("詳解在 Ubuntu 中引導到救援模式或緊急模式 "),s("a",{class:"header-anchor",href:"#詳解在-ubuntu-中引導到救援模式或緊急模式","aria-label":"Permalink to “詳解在 Ubuntu 中引導到救援模式或緊急模式”"},"​")],-1)),t[22]||(t[22]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202206/14/153639n33fg3e2gc7xnvv3.jpg",alt:""})],-1)),t[23]||(t[23]=s("p",null,[e("這篇教程將介紹如何在 Ubuntu 22.04、20.04 和 18.04 LTS 版本中引導到 "),s("ruby",null,[e("救援"),s("rt",null,"Rescue")]),e(" 模式或 "),s("ruby",null,[e("緊急"),s("rt",null,"Emergency")]),e(" 模式。")],-1)),s("blockquote",null,[s("p",null,[t[1]||(t[1]=a("你可能已經知道，在 RHEL 7 、RHEL 8 、Ubuntu 16.04 LTS 及其更新的版本的 Linux 發行版中 <ruby>運行等級<rt>Runlevels</rt></ruby> 已經被 <ruby>系統目標<rt>Systemd target</rt></ruby> 所替代。更多關於 <ruby>運行等級<rt>Runlevel</rt></ruby> 和 <ruby>系統目標<rt>Systemd targets</rt></ruby> 的信息，參考 ",9)),o(n,{href:"https://ostechnix.com/check-runlevel-linux/"},{default:i(()=>[...t[0]||(t[0]=[e("這篇指南",-1)])]),_:1}),t[2]||(t[2]=e(" 。",-1))])]),t[24]||(t[24]=a('<p>這篇指南是針對 Ubuntu 編寫的，但是，下面所給的步驟應該也適用於大多數使用 systemd 作為默認服務管理器的 Linux 發行版。</p><p>在進入主題前，讓我們簡單的理解：什麼是 <ruby>救援<rt>rescue</rt></ruby> 模式 和 <ruby>緊急<rt>Emergency</rt></ruby> 模式，以及這兩種模式的目的是什麼。</p><h3 id="什麼是救援模式" tabindex="-1">什麼是救援模式？ <a class="header-anchor" href="#什麼是救援模式" aria-label="Permalink to “什麼是救援模式？”">​</a></h3><p>在 Linux 發行版中，救援模式等效於使用 SysV 作為默認的服務器管理器的 <ruby>單用户<rt>single user</rt></ruby> 模式。在救援模式中，將掛載所有的本地文件系統，將僅啓動一些重要的服務。但是，不會啓動一般的服務（例如，網絡服務）。</p>',4)),s("p",null,[t[4]||(t[4]=e("救援模式在不能正常引導系統的情況下是很有用的。此外，我們可以在救援模式下執行一些重要的救援操作，例如，",-1)),o(n,{href:"https://ostechnix.com/how-to-reset-or-recover-root-user-password-in-linux/"},{default:i(()=>[...t[3]||(t[3]=[e("重新設置 root 密碼",-1)])]),_:1}),t[5]||(t[5]=e(" 。",-1))]),t[25]||(t[25]=a('<h3 id="什麼是緊急模式" tabindex="-1">什麼是緊急模式？ <a class="header-anchor" href="#什麼是緊急模式" aria-label="Permalink to “什麼是緊急模式？”">​</a></h3><p>與救援模式相比，在緊急模式中，不會啓動任何的東西。不會啓動服務、不會掛載掛載點、不會建立套接字、什麼都不會啓動。你將所擁有的只是一個 <strong>原始的 shell</strong> 。緊急模式適用於調試目的。</p><p>首先，我們將看到如何在 Ubuntu 22.04 和 20.04 LTS 發行版中引導到救援模式或緊急模式。在 Ubuntu 22.04 和 20.04 LTS 中的過程是完全相同的！</p><h3 id="在-ubuntu-22-04-20-04-lts-中引導到救援模式" tabindex="-1">在 Ubuntu 22.04 / 20.04 LTS 中引導到救援模式 <a class="header-anchor" href="#在-ubuntu-22-04-20-04-lts-中引導到救援模式" aria-label="Permalink to “在 Ubuntu 22.04 / 20.04 LTS 中引導到救援模式”">​</a></h3><p>我們可以使用兩種方法來引導到救援模式。</p><h4 id="方法-1" tabindex="-1">方法 1 <a class="header-anchor" href="#方法-1" aria-label="Permalink to “方法 1”">​</a></h4><p>打開你的 Ubuntu 系統。在 BIOS 徽標出現後，按下 <code>ESC</code> 按鍵來顯示 GRUB 菜單。</p><p>在 GRUB 菜單中，選擇第一項，並按下 <code>e</code> 按鍵來編輯它。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/GRUB-Menu-In-Ubuntu-22.04-LTS.png" alt="GRUB Menu In Ubuntu 22.04 / 20.04 LTS"></p><p>按下 <code>↓</code> 按鍵，並找到以單詞 <code>linux</code> 開頭的一行代碼，並在其結尾處添加下面的一行代碼。為到達其結尾處，只需要按下 <code>Ctrl + e</code> 組合鍵，或使用你鍵盤上的 <code>END</code> 按鍵或 <code>←</code>/<code>→</code> 按鍵。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemd.unit=rescue.target</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Edit-Grub-Boot-Menu-Entries-To-Enter-Into-Rescue-Mode-In-Ubuntu-22.04-LTS.png" alt="Edit Grub Boot Menu Entries To Enter Into Rescue Mode In Ubuntu 22.04 / 20.04 LTS"></p><p>在添加上面的代碼行後，按下 <code>Ctrl + x</code> 組合鍵或按下 <code>F10</code> 按鍵來引導到救援模式。</p><p>數秒後，你將作為 root 用户來登錄到救援模式（即單用户模式）。將會提示你按下回車鍵來進入維護。</p><p>下圖是 Ubuntu 22.04 / 20.04 LTS 系統的救援模式的樣子：</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Boot-Into-Rescue-Mode-In-Ubuntu-22.04.png" alt="Boot Into Rescue Mode In Ubuntu 22.04 / 20.04 LTS"></p><p>現在，在救援模式中做你想做的任何事。在救援模式中，在你執行任何操作前，你可能需要以 讀/寫模式來掛載根（<code>/</code>）文件系統。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mount -n -o remount,rw /</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Mount-Root-File-System-In-Read-Write-Mode-In-Ubuntu.png" alt="Mount Root File System In Read Write Mode In Ubuntu 22.04 / 20.04 LTS"></p><p>在完成後，按下 <code>Ctrl + d</code> 組合鍵來引導到正常模式。或者，你可以輸入下面的任意一個命令來引導到正常模式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl default</span></span></code></pre></div><p>或者，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>exit</span></span></code></pre></div><p>如果你想重新啓動系統，而不是引導到正常的模式，輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl reboot</span></span></code></pre></div><h4 id="方法-2" tabindex="-1">方法 2 <a class="header-anchor" href="#方法-2" aria-label="Permalink to “方法 2”">​</a></h4><p>在這種方法中，你不需要編輯 GRUB 啓動菜單項目。</p><p>打開系統電源，並從 GRUB 啓動菜單中選擇 <ruby>Ubuntu 高級選項<rt>Advanced options for Ubuntu</rt></ruby>。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Choose-Advanced-Options-For-Ubuntu-From-Grub-Boot-Menu.png" alt="Choose Advanced Options For Ubuntu From Grub Boot Menu"></p><p>接下來，你將看到一個帶有內核版本的可用的 Ubuntu 版本的列表。在 Ubuntu 中的 GRUB 啓動菜單中選擇 <ruby>恢復模式<rt>Recovery mode</rt></ruby> 。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Choose-Recovery-Mode-In-Grub-Boot-Menu-In-Ubuntu.png" alt="Choose Recovery Mode In Grub Boot Menu In Ubuntu 22.04 / 20.04 LTS"></p><p>數秒後，你將看到 Ubuntu 的 <ruby>恢復<rt>Recovery</rt></ruby> 菜單。從恢復菜單中，選擇 <ruby>進入 root 的 shell 提示符<rt>Drop to root shell prompt</rt></ruby> 選項 ，並按下回車鍵。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Enter-Into-Root-Shell-Prompt-In-Ubuntu.png" alt="Enter Into Root Shell Prompt In Ubuntu 22.04 / 20.04 LTS"></p><p>現在，你將進入維護。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Ubuntu-Maintenance-Mode.png" alt="Ubuntu Maintenance Mode"></p><p>通過輸入下面的命令來 以讀/寫模式的方式 來掛載根（<code>/</code>）文件系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mount -n -o remount,rw /</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Mount-Root-File-System-In-Read-Write-Mode-In-Ubuntu-1.png" alt="Mount Root File System In Read Write Mode In Ubuntu"></p><p>在救援模式中做你想做的任何事。</p><p>在完成後，輸入 <code>exit</code> 來返回到恢復菜單。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>exit</span></span></code></pre></div><p>最後，選擇 <ruby>救援正常啓動<rt>Resume normal boot</rt></ruby> 選項，並按下回車鍵。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Boot-Into-Normal-Mode-In-Ubuntu.png" alt="Boot Into Normal Mode In Ubuntu"></p><p>再次按下回車鍵來退出恢復模式，並繼續引導到正常模式。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Exit-The-Recovery-Mode-In-Ubuntu.png" alt="Exit The Recovery Mode In Ubuntu"></p><p>如果你不想引導到正常模式，從救援模式中輸入 <code>reboot</code> 並按下回車鍵來重新啓動你的系統。</p><h3 id="在-ubuntu-22-04-20-04-lts-中引導到緊急模式" tabindex="-1">在 Ubuntu 22.04 / 20.04 LTS 中引導到緊急模式 <a class="header-anchor" href="#在-ubuntu-22-04-20-04-lts-中引導到緊急模式" aria-label="Permalink to “在 Ubuntu 22.04 / 20.04 LTS 中引導到緊急模式”">​</a></h3><p>當 GRUB 菜單出現時，按下 <code>e</code> 按鍵來編輯它。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/GRUB-Menu-In-Ubuntu-22.04-LTS.png" alt="GRUB Menu In Ubuntu 22.04 / 20.04 LTS"></p><p>找到以單詞 <code>linux</code> 開頭的一行代碼，並在其結尾處添加下面的一行代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemd.unit=emergency.target</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Edit-Grub-Boot-Menu-Entries-To-Enter-Into-Emergency-Mode-In-Ubuntu.png" alt="Edit Grub Boot Menu Entries To Enter Into Emergency Mode In Ubuntu 22.04 / 20.04 LTS"></p><p>在添加上面的代碼行後，按下 <code>Ctrl + x</code> 組合鍵，或按下 <code>F10</code> 按鍵來引導到緊急模式。</p><p>數秒後，你將作為 <code>root</code> 用户來進入維護。將會提示你按下回車鍵來進入緊急模式。</p><p>下圖是 Ubuntu 22.04 / 20.04 LTS 系統的緊急模式的樣子：</p><p><img src="https://ostechnix.com/wp-content/uploads/2018/12/Boot-Into-Emergency-Mode-In-Ubuntu-20.04-LTS.png" alt="Boot Into Emergency Mode In Ubuntu 22.04 / 20.04 LTS"></p><p>現在，在緊急模式中做你想做的任何事。在緊急模式中，在你執行任何操作前，你可能需要以讀/寫模式來掛載根（<code>/</code>）文件系統。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mount -n -o remount,rw /</span></span></code></pre></div><p>在完成後，按下 <code>Ctrl + d</code> 組合鍵來引導到正常模式。或者，你可以輸入下面的任意一個命令來引導到正常模式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl default</span></span></code></pre></div><p>或者，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>exit</span></span></code></pre></div><p>如果你想重新啓動系統，而不是引導到正常模式，輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl reboot</span></span></code></pre></div><h3 id="在-ubuntu-18-04-lts-中引導到救援模式" tabindex="-1">在 Ubuntu 18.04 LTS 中引導到救援模式 <a class="header-anchor" href="#在-ubuntu-18-04-lts-中引導到救援模式" aria-label="Permalink to “在 Ubuntu 18.04 LTS 中引導到救援模式”">​</a></h3><p>啓動你的 Ubuntu 系統。當 GRUB 菜單出現時，選擇第一項並按下按鍵 <code>e</code> 來編輯。（為到達其行尾處，只需要按下 <code>Ctrl + e</code> 組合鍵，或使用你鍵盤上的 <code>END</code> 按鍵或 <code>←</code>/<code>→</code> 按鍵）：</p><p><img src="https://ostechnix.com/wp-content/uploads/2018/12/Grub-menu.png" alt="Grub Menu"></p><p>如果你沒有看到 GRUB 菜單，只需要在 BIOS 徽標出現後，按下 <code>ESC</code> 按鍵來顯示 GRUB 菜單。</p><p>找到以單詞 <code>linux</code> 開頭的一行代碼，並在其結尾處添加下面的一行代碼（為到達其行尾處，只需要按下 <code>Ctrl + e</code> 組合鍵，或使用你鍵盤上的 END<code>按鍵或</code>←<code>/</code>→` 按鍵）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemd.unit=rescue.target</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2018/12/Edit-grub-menu.png" alt="Edit Grub Menu"></p><p>在添加上面的代碼行後，只需要按下 <code>Ctrl + x</code> 組合鍵，或按下 <code>F10</code> 按鍵來引導到救援模式。數秒後，你將作為 <code>root</code> 用户進入維護（即單用户模式）。</p><p>下圖是 Ubuntu 18.04 LTS 服務器系統的救援模式的樣子：</p><p><img src="https://ostechnix.com/wp-content/uploads/2018/12/Ubuntu-rescue-mode.png" alt="Ubuntu Rescue Mode"></p><p>接下來，輸入下面的命令來掛載根（<code>/</code>）文件系統為讀/寫模式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mount -n -o remount,rw /</span></span></code></pre></div><h3 id="在-ubuntu-18-04-lts-中引導到緊急模式" tabindex="-1">在 Ubuntu 18.04 LTS 中引導到緊急模式 <a class="header-anchor" href="#在-ubuntu-18-04-lts-中引導到緊急模式" aria-label="Permalink to “在 Ubuntu 18.04 LTS 中引導到緊急模式”">​</a></h3><p>引導你的 Ubuntu 到緊急模式基本與上述方法相同。你所需要做的全部工作是，在編輯 GRUB 菜單時，將 <code>systemd.unit=rescue.target</code> 替換為 <code>systemd.unit=emergency.target</code> 。</p><p><img src="https://ostechnix.com/wp-content/uploads/2018/12/emergency-mode.png" alt="Edit Grub Menu"></p><p>在你添加 <code>systemd.unit=emergency.target</code> 後，按下 <code>Ctrl + x</code> 組合鍵，或按下 <code>F10</code> 按鍵來引導到緊急模式。</p><p><img src="https://ostechnix.com/wp-content/uploads/2018/12/emergency-mode-1.png" alt="Ubuntu Emergency Mode"></p><p>最後，你可以使用下面的命令來以讀/寫模式的方式來掛載根（<code>/</code>）文件系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mount -n -o remount,rw /</span></span></code></pre></div><h3 id="在救援模式和緊急模式之間切換" tabindex="-1">在救援模式和緊急模式之間切換 <a class="header-anchor" href="#在救援模式和緊急模式之間切換" aria-label="Permalink to “在救援模式和緊急模式之間切換”">​</a></h3><p>如果你正在救援模式中，你不必像我上述提到的那樣來編輯 GRUB 的菜單啓動項。相反，你只想要輸入下面的命令來立刻切換到緊急模式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl emergency</span></span></code></pre></div><p>同樣，為從緊急模式切換到救援模式，輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl rescue</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>現在，你知道了什麼是救援模式和緊急模式，以及如何在 Ubuntu 22.04 、20.04 和 18.04 LTS 系統中啓動到這些模式。正如我已經提到的，在這裏提供的這些步驟應該也適用於大多數當前使用 systemd 作為默認服務管理器的 Linux 發行版。</p><hr>',91)),s("p",null,[t[7]||(t[7]=e("via: ",-1)),o(n,{href:"https://ostechnix.com/how-to-boot-into-rescue-mode-or-emergency-mode-in-ubuntu-18-04/"},{default:i(()=>[...t[6]||(t[6]=[e("https://ostechnix.com/how-to-boot-into-rescue-mode-or-emergency-mode-in-ubuntu-18-04/",-1)])]),_:1})]),s("p",null,[t[12]||(t[12]=e("作者：",-1)),o(n,{href:"https://ostechnix.com/author/sk/"},{default:i(()=>[...t[8]||(t[8]=[e("sk",-1)])]),_:1}),t[13]||(t[13]=e(" 選題：",-1)),o(n,{href:"https://github.com/lkxed"},{default:i(()=>[...t[9]||(t[9]=[e("lkxed",-1)])]),_:1}),t[14]||(t[14]=e(" 譯者：",-1)),o(n,{href:"https://github.com/robsean"},{default:i(()=>[...t[10]||(t[10]=[e("robsean",-1)])]),_:1}),t[15]||(t[15]=e(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:i(()=>[...t[11]||(t[11]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[18]||(t[18]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[16]||(t[16]=[e("LCTT",-1)])]),_:1}),t[19]||(t[19]=e(" 原創編譯，",-1)),o(n,{href:"https://linux.cn/"},{default:i(()=>[...t[17]||(t[17]=[e("Linux中國",-1)])]),_:1}),t[20]||(t[20]=e(" 榮譽推出",-1))])])}const U=l(d,[["render",c]]);export{x as __pageData,U as default};
